// Script de Nodo para CharacterBody3D. Configura las acciones desde Input Map.
// Jolt integra el cuerpo una sola vez por paso físico; no se teletransporta el nodo.
const WALK_SPEED = 3
const RUN_SPEED = 5.5
const ACCELERATION = 16
const DECELERATION = 20
const JUMP_SPEED = 5

let jumpPending = false

function _ready() {
  jumpPending = false
}

function _process(delta) {
  // Conserva una pulsación aunque este fotograma no tenga paso físico.
  if (game.input.justPressed('jump')) jumpPending = true
}

function _physics_process(delta) {
  const { x, y } = game.input.vector('move_left', 'move_right', 'move_back', 'move_forward')
  const speed = game.input.pressed('run') ? RUN_SPEED : WALK_SPEED
  const yaw = node.rotation[1] * Math.PI / 180
  const sin = Math.sin(yaw), cos = Math.cos(yaw)
  const targetX = (cos * x - sin * y) * speed
  const targetZ = (-sin * x - cos * y) * speed
  const velocity = node.velocity
  const differenceX = targetX - velocity[0], differenceZ = targetZ - velocity[2]
  const distance = Math.hypot(differenceX, differenceZ)
  const rate = x || y ? ACCELERATION : DECELERATION
  const change = Math.min(distance, rate * Math.max(0, delta))
  const ratio = distance > 0 ? change / distance : 0
  const nextX = velocity[0] + differenceX * ratio
  const nextZ = velocity[2] + differenceZ * ratio
  const nextY = jumpPending && node.onFloor ? JUMP_SPEED : velocity[1]
  jumpPending = false
  node.velocity = [nextX, nextY, nextZ]
}

